1	/**
2	 * Pure positioning math for the persona-note popover. Lives in its
3	 * own module so the editor can import it (no Qwik dependency) and
4	 * so the placement rules — "prefer below the sentence, flip fully
5	 * above when the bottom would clip (never overlap the marked text),
6	 * and clamp height to the available room on whichever side wins" —
7	 * are unit-testable without a Tiptap editor.
8	 */
9	
10	export const POPOVER_CARD_WIDTH = 340;
11	export const POPOVER_CARD_MARGIN = 8;
12	export const MARGIN_CARD_GAP = 12;
13	/**
14	 * The popover's *content*-driven height. The CSS rule that the
15	 * card inflates to lives inside the JSX; this is the "ideal" we ask
16	 * for when there is room below the sentence. The renderer clamps the
17	 * final `maxH` to the available space on the chosen side.
18	 */
19	export const POPOVER_CARD_IDEAL_HEIGHT = 520;
20	
21	export type PopoverPlacement = "below" | "above";
22	
23	export interface PopoverGeometry {
24	  /** The card's top-left x in viewport coordinates. */
25	  x: number;
26	  /** Top offset in px (or null when the card is bottom-anchored above). */
27	  top: number | null;
28	  /** Bottom offset in px (or null when the card is top-anchored below). */
29	  bottom: number | null;
30	  /** Final max-height in px, clamped to the available space on the chosen side. */
31	  maxH: number;
32	  /** Which side of the anchor the card sits on. */
33	  placement: PopoverPlacement;
34	}
35	
36	export interface AnchorRect {
37	  left: number;
38	  top: number;
39	  bottom: number;
40	}
41	
42	export interface PopoverView {
43	  /** Viewport width. */
44	  vw: number;
45	  /** Viewport height. */
46	  vh: number;
47	  /** The marked span's bounding rect. */
48	  rect: AnchorRect;
49	  /** Ideal card height; defaults to POPOVER_CARD_IDEAL_HEIGHT. */
50	  idealH?: number;
51	}
52	
53	export interface MarginCardView extends PopoverView {
54	  /** The visible manuscript page whose outside margins the card should use. */
55	  page: { left: number; right: number };
56	}
57	
58	/**
59	 * Place an editorial conversation beside the manuscript, Google-Docs style.
60	 * The right margin is the stable default; the left margin is used when it is
61	 * the only side with room. Narrow viewports fall back to a clamped edge card,
62	 * with CSS turning that card into a bottom sheet on phones.
63	 */
64	export function computeMarginCardGeometry(
65	  view: MarginCardView,
66	): PopoverGeometry {
67	  const margin = MARGIN_CARD_GAP;
68	  const cardWidth = POPOVER_CARD_WIDTH;
69	  const idealH = view.idealH ?? POPOVER_CARD_IDEAL_HEIGHT;
70	  const rightX = view.page.right + margin;
71	  const leftX = view.page.left - cardWidth - margin;
72	  const rightFits = rightX + cardWidth <= view.vw - margin;
73	  const leftFits = leftX >= margin;
74	
75	  let x: number;
76	  if (rightFits) x = rightX;
77	  else if (leftFits) x = leftX;
78	  else {
79	    const roomRight = view.vw - view.page.right;
80	    const roomLeft = view.page.left;
81	    x = roomRight >= roomLeft ? rightX : leftX;
82	    x = Math.max(margin, Math.min(x, view.vw - cardWidth - margin));
83	  }
84	
85	  const maxH = Math.max(0, Math.min(idealH, view.vh - margin * 2));
86	  const top = Math.max(
87	    margin,
88	    Math.min(view.rect.top, view.vh - maxH - margin),
89	  );
90	
91	  return { x, top, bottom: null, maxH, placement: "below" };
92	}
93	
94	/**
95	 * Decide where the popover should sit relative to the marked passage.
96	 *
97	 * Rules:
98	 *  1. Prefer just below the sentence (`rect.bottom + margin`).
99	 *  2. If the ideal card would clip the viewport bottom and there is
100	 *     strictly *more* room above than below, flip above. The flipped
101	 *     card is bottom-anchored so it grows upward from `rect.top - margin` —
102	 *     this matters because the card's final height is content-dependent,
103	 *     so a top-anchored flip would jitter as content streams in.
104	 *  3. Whichever side wins, clamp `maxH` to the available space so the
105	 *     card never overlaps the anchor.
106	 */
107	export function computePopoverGeometry(view: PopoverView): PopoverGeometry {
108	  const margin = POPOVER_CARD_MARGIN;
109	  const idealH = view.idealH ?? POPOVER_CARD_IDEAL_HEIGHT;
110	
111	  const x = Math.max(
112	    margin,
113	    Math.min(view.rect.left, view.vw - POPOVER_CARD_WIDTH - margin),
114	  );
115	
116	  const belowTop = view.rect.bottom + margin;
117	  const aboveBottomCoord = view.rect.top - margin;
118	
119	  const spaceBelow = Math.max(0, view.vh - margin - belowTop);
120	  const spaceAbove = Math.max(0, aboveBottomCoord - margin);
121	
122	  // Default: below. Only flip above if below can't fit AND above is strictly
123	  // roomier. Equal falls through to below — keeps behavior stable when the
124	  // anchor is roughly mid-viewport.
125	  const flipAbove = spaceBelow < idealH && spaceAbove > spaceBelow;
126	
127	  if (flipAbove) {
128	    const maxH = Math.max(0, Math.min(idealH, spaceAbove));
129	    // bottom offset relative to viewport: vh - rect.top + margin
130	    return {
131	      x,
132	      top: null,
133	      bottom: Math.max(0, view.vh - view.rect.top + margin),
134	      maxH,
135	      placement: "above",
136	    };
137	  }
138	
139	  const maxH = Math.max(0, Math.min(idealH, spaceBelow));
140	  return {
141	    x,
142	    top: belowTop,
143	    bottom: null,
144	    maxH,
145	    placement: "below",
146	  };
147	}
148

