1	import type { EditorCommandContext } from "./editor-commands";
2	import {
3	  getSlashCommands,
4	  type EditorCommandDefinition,
5	} from "./editor-commands";
6	import { shortcutHints, type ShortcutPlatform } from "./keybindings";
7	
8	export interface SlashCommandCandidate {
9	  command: EditorCommandDefinition;
10	  score: number;
11	  shortcut: string | null;
12	}
13	
14	function normalise(value: string): string {
15	  return value
16	    .toLocaleLowerCase()
17	    .replace(/[^a-z0-9]+/g, " ")
18	    .trim();
19	}
20	
21	/**
22	 * Small fuzzy scorer tuned for command menus.
23	 *
24	 * Exact prefixes win, then word prefixes, then ordered subsequences. A query
25	 * that cannot be found in order is excluded rather than returning every
26	 * command with an arbitrary low score.
27	 */
28	export function fuzzyCommandScore(
29	  command: EditorCommandDefinition,
30	  query: string,
31	): number | null {
32	  const needle = normalise(query);
33	  if (!needle) return 0;
34	
35	  const label = normalise(command.label);
36	  const haystack = normalise(
37	    [
38	      command.label,
39	      command.description,
40	      command.id,
41	      ...command.searchTerms,
42	      ...(command.slash?.keywords ?? []),
43	    ].join(" "),
44	  );
45	
46	  if (label === needle) return 1000;
47	  if (label.startsWith(needle)) return 800 - (label.length - needle.length);
